// Error Trigger -> one normalized, SECRET-REDACTED record. No HTML here (escaping happens in 'Build alert message').
// Two shapes exist:
//   execution error: { workflow:{id,name}, execution:{id,url,mode,lastNodeExecuted,error:{message,stack}} }
//   trigger error:   { workflow:{id,name}, trigger:{mode:'trigger', error:{message,node:{name},cause:{message}}} }
const SELF = 'Workflow C - Global error handler';
const redact = (s) => {
  let t = String(s === undefined || s === null ? '' : s);
  return t
    .replace(/\bya29\.[A-Za-z0-9._-]+/g, '[REDACTED]')
    .replace(/\b1\/\/[A-Za-z0-9._-]{20,}/g, '[REDACTED]')
    .replace(/\b(bearer|basic)\s+[A-Za-z0-9._~+\/=-]{8,}/gi, '$1 [REDACTED]')
    .replace(/(x-api-key|api[_-]?key|apikey|authorization|password|passwd|pwd|secret|token|encryption[_-]?key)(["']?\s*[:=]\s*["']?)[^\s"',;&}]+/gi, '$1$2[REDACTED]')
    .replace(/([?&](?:token|key|api_key|apikey|password|secret|access_token)=)[^&\s]+/gi, '$1[REDACTED]')
    .replace(/\b(?:sk|pk|rk)-[A-Za-z0-9_-]{16,}/g, '[REDACTED]');
};
const clip = (s, n) => { const t = String(s).replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n - 1) + '\u2026' : t; };
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const wf = j.workflow || {};
  const ex = j.execution || {};
  const tr = j.trigger || {};
  const err = ex.error || tr.error || {};
  const isTrigger = !j.execution && !!j.trigger;
  const rawMsg = err.message || (err.cause && err.cause.message) || (typeof err === 'string' ? err : '') || 'unknown error';
  const nodeName = ex.lastNodeExecuted || (err.node && (err.node.name || (typeof err.node === 'string' ? err.node : ''))) || (isTrigger ? 'trigger' : 'unknown');
  const workflowName = wf.name || 'unknown workflow';
  if (workflowName === SELF) continue;           // never alert about this handler itself (no loops)
  const message = clip(redact(rawMsg), 300);
  const norm = message.toLowerCase().replace(/\d+/g, '#').slice(0, 120);
  out.push({ json: {
    workflow_id: wf.id !== undefined ? String(wf.id) : '',
    workflow_name: clip(redact(workflowName), 100),
    node_name: clip(redact(nodeName), 100),
    message,
    execution_id: ex.id !== undefined ? String(ex.id) : '',
    mode: String(ex.mode || tr.mode || ''),
    kind: isTrigger ? 'trigger' : 'execution',
    key: [wf.id !== undefined ? String(wf.id) : workflowName, nodeName, norm].join('|').slice(0, 250),
  } });
}
return out;

// Storm protection, state kept in workflow static data (survives between executions).
//  1) same error (workflow + node + message with digits normalised) at most once per COOLDOWN_MIN minutes;
//     suppressed repeats are counted and reported on the next alert for that error.
//  2) at most MAX_PER_WINDOW alerts per WINDOW_MIN minutes across ALL errors; the first alert over the cap
//     is replaced by ONE "storm" notice, everything else in the window is dropped.
const COOLDOWN_MIN = 15, WINDOW_MIN = 10, MAX_PER_WINDOW = 6, MAX_KEYS = 200, KEEP_HOURS = 24;
const sd = $getWorkflowStaticData('global');
const st = sd.errorThrottle = sd.errorThrottle || { keys: {}, win: { start: 0, count: 0, notice: false } };
const now = Date.now();
const MIN = 60000;

// prune old keys
for (const k of Object.keys(st.keys)) { if (now - st.keys[k].last > KEEP_HOURS * 60 * MIN) delete st.keys[k]; }
const ks = Object.keys(st.keys);
if (ks.length > MAX_KEYS) { ks.sort((a, b) => st.keys[a].last - st.keys[b].last).slice(0, ks.length - MAX_KEYS).forEach((k) => delete st.keys[k]); }

const out = [];
for (const it of $input.all()) {
  const e = it.json;
  const prev = st.keys[e.key];
  if (prev && now - prev.last < COOLDOWN_MIN * MIN) { prev.suppressed += 1; continue; }

  if (now - st.win.start >= WINDOW_MIN * MIN) st.win = { start: now, count: 0, notice: false };
  if (st.win.count >= MAX_PER_WINDOW) {
    if (prev) prev.suppressed += 1; else st.keys[e.key] = { last: 0, suppressed: 1 };
    if (!st.win.notice) {
      st.win.notice = true;
      out.push({ json: { storm: true, workflow_name: e.workflow_name, node_name: e.node_name, message: e.message, execution_id: e.execution_id, mode: e.mode, window_min: WINDOW_MIN, max: MAX_PER_WINDOW, suppressed_before: 0 } });
    }
    continue;
  }
  st.win.count += 1;
  const before = prev ? prev.suppressed : 0;
  st.keys[e.key] = { last: now, suppressed: 0 };
  out.push({ json: Object.assign({}, e, { storm: false, suppressed_before: before }) });
}
return out;

// Throttled record -> Gmail item. Plain text (no HTML), so nothing needs escaping.
let admin = '';
try { admin = String($env.ADMIN_EMAIL || '').trim(); } catch (e) { admin = ''; }
if (!admin) return [];                       // no admin email configured -> nothing to send
const s = (v) => String(v === undefined || v === null ? '' : v);
const out = [];
for (const it of $input.all()) {
  const e = it.json;
  let subject, body;
  if (e.storm) {
    subject = '[Tutor] Error storm';
    body = 'More than ' + s(e.max) + ' errors within ' + s(e.window_min) + ' min. Further alerts are paused until the window ends.\n' +
      'latest: ' + s(e.workflow_name) + ' / ' + s(e.node_name) + '\nerror: ' + s(e.message);
  } else {
    subject = '[Tutor] n8n error: ' + s(e.workflow_name).slice(0, 60);
    body = 'workflow: ' + s(e.workflow_name) + '\nnode: ' + s(e.node_name) + '\nerror: ' + s(e.message) + '\n' +
      'execution: ' + s(e.execution_id || 'n/a') + (e.mode ? ' (' + s(e.mode) + ')' : '') +
      (e.kind === 'trigger' ? '\ntrigger/activation error (check the Gmail OAuth credential)' : '') +
      (e.suppressed_before > 0 ? '\n+' + s(e.suppressed_before) + ' similar suppressed since the last alert' : '');
  }
  out.push({ json: { to: admin, subject, body: body.slice(0, 3500) } });
}
return out;
